// src/App.js
import React, { useState, useEffect, useRef } from 'react';
import * as THREE from 'three';
import LoginModal from './components/LoginModal';

function App() {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [user, setUser] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const mountRef = useRef(null);
  const sceneRef = useRef(null);
  const cameraRef = useRef(null);
  const rendererRef = useRef(null);
  const blackHoleRef = useRef(null);
  const accretionDiskRef = useRef(null);
  const particleSystemRef = useRef(null);

  // Check for existing session
  useEffect(() => {
    const checkAuth = () => {
      try {
        const storedUser = localStorage.getItem('user');
        const isLoggedIn = localStorage.getItem('isLoggedIn');

        if (storedUser && isLoggedIn === 'true') {
          const userData = JSON.parse(storedUser);
          setUser(userData);
        }
      } catch (error) {
        console.error('Auth check error:', error);
      } finally {
        setIsLoading(false);
      }
    };

    checkAuth();
  }, []);

  // Initialize Black Hole Three.js Scene
  useEffect(() => {
    if (!mountRef.current) return;

    // Scene setup
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x000000);
    scene.fog = new THREE.FogExp2(0x000000, 0.008);
    sceneRef.current = scene;

    // Camera setup
    const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 1000);
    camera.position.set(0, 3, 12);
    camera.lookAt(0, 0, 0);
    cameraRef.current = camera;

    // Renderer setup
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(window.devicePixelRatio);
    renderer.shadowMap.enabled = true;
    mountRef.current.appendChild(renderer.domElement);
    rendererRef.current = renderer;

    // Lighting
    // Ambient light
    const ambientLight = new THREE.AmbientLight(0x111111);
    scene.add(ambientLight);

    // Point light for the black hole glow
    const pointLight = new THREE.PointLight(0x8844aa, 1, 20);
    pointLight.position.set(0, 0, 0);
    scene.add(pointLight);

    // Additional colored lights
    const redLight = new THREE.PointLight(0xff3366, 0.5);
    redLight.position.set(2, 1, 2);
    scene.add(redLight);

    const blueLight = new THREE.PointLight(0x33ff66, 0.5);
    blueLight.position.set(-2, -1, 2);
    scene.add(blueLight);

    // Background stars
    const starGeometry = new THREE.BufferGeometry();
    const starCount = 3000;
    const starPositions = new Float32Array(starCount * 3);
    for (let i = 0; i < starCount; i++) {
      starPositions[i * 3] = (Math.random() - 0.5) * 200;
      starPositions[i * 3 + 1] = (Math.random() - 0.5) * 100;
      starPositions[i * 3 + 2] = (Math.random() - 0.5) * 100 - 50;
    }
    starGeometry.setAttribute('position', new THREE.BufferAttribute(starPositions, 3));
    const starMaterial = new THREE.PointsMaterial({ color: 0xffffff, size: 0.15, transparent: true, opacity: 0.8 });
    const stars = new THREE.Points(starGeometry, starMaterial);
    scene.add(stars);

    // Twinkling stars (second layer)
    const starGeometry2 = new THREE.BufferGeometry();
    const starCount2 = 1500;
    const starPositions2 = new Float32Array(starCount2 * 3);
    for (let i = 0; i < starCount2; i++) {
      starPositions2[i * 3] = (Math.random() - 0.5) * 250;
      starPositions2[i * 3 + 1] = (Math.random() - 0.5) * 150;
      starPositions2[i * 3 + 2] = (Math.random() - 0.5) * 150 - 80;
    }
    starGeometry2.setAttribute('position', new THREE.BufferAttribute(starPositions2, 3));
    const starMaterial2 = new THREE.PointsMaterial({ color: 0xaaccff, size: 0.1, transparent: true, opacity: 0.6 });
    const stars2 = new THREE.Points(starGeometry2, starMaterial2);
    scene.add(stars2);

    // BLACK HOLE CENTER (Event Horizon)
    const eventHorizonGeometry = new THREE.SphereGeometry(0.8, 64, 64);
    const eventHorizonMaterial = new THREE.MeshStandardMaterial({
      color: 0x000000,
      emissive: 0x110000,
      roughness: 0.1,
      metalness: 0.9,
      emissiveIntensity: 0.5
    });
    const eventHorizon = new THREE.Mesh(eventHorizonGeometry, eventHorizonMaterial);
    eventHorizon.castShadow = true;
    scene.add(eventHorizon);
    blackHoleRef.current = eventHorizon;

    // Inner glow sphere
    const innerGlowGeometry = new THREE.SphereGeometry(0.95, 64, 64);
    const innerGlowMaterial = new THREE.MeshBasicMaterial({
      color: 0x442266,
      transparent: true,
      opacity: 0.3,
      blending: THREE.AdditiveBlending
    });
    const innerGlow = new THREE.Mesh(innerGlowGeometry, innerGlowMaterial);
    scene.add(innerGlow);

    // ACCRETION DISK (Spinning matter around black hole)
    const diskParticleCount = 8000;
    const diskGeometry = new THREE.BufferGeometry();
    const diskPositions = new Float32Array(diskParticleCount * 3);
    const diskColors = new Float32Array(diskParticleCount * 3);

    for (let i = 0; i < diskParticleCount; i++) {
      const radius = 1.2 + Math.random() * 2.5;
      const angle = Math.random() * Math.PI * 2;
      const yOffset = (Math.random() - 0.5) * 0.4;

      diskPositions[i * 3] = Math.cos(angle) * radius;
      diskPositions[i * 3 + 1] = yOffset;
      diskPositions[i * 3 + 2] = Math.sin(angle) * radius;

      // Colors from red to blue to white
      const colorChoice = Math.random();
      if (colorChoice < 0.33) {
        diskColors[i * 3] = 1.0;
        diskColors[i * 3 + 1] = 0.2 + Math.random() * 0.3;
        diskColors[i * 3 + 2] = 0.2;
      } else if (colorChoice < 0.66) {
        diskColors[i * 3] = 0.8;
        diskColors[i * 3 + 1] = 0.4 + Math.random() * 0.4;
        diskColors[i * 3 + 2] = 1.0;
      } else {
        diskColors[i * 3] = 1.0;
        diskColors[i * 3 + 1] = 0.8 + Math.random() * 0.2;
        diskColors[i * 3 + 2] = 0.6 + Math.random() * 0.4;
      }
    }

    diskGeometry.setAttribute('position', new THREE.BufferAttribute(diskPositions, 3));
    diskGeometry.setAttribute('color', new THREE.BufferAttribute(diskColors, 3));

    const diskMaterial = new THREE.PointsMaterial({
      size: 0.04,
      vertexColors: true,
      blending: THREE.AdditiveBlending,
      transparent: true,
      opacity: 0.9
    });

    const accretionDisk = new THREE.Points(diskGeometry, diskMaterial);
    scene.add(accretionDisk);
    accretionDiskRef.current = accretionDisk;

    // Outer ring (gas and dust)
    const ringParticleCount = 4000;
    const ringGeometry = new THREE.BufferGeometry();
    const ringPositions = new Float32Array(ringParticleCount * 3);
    const ringColors = new Float32Array(ringParticleCount * 3);

    for (let i = 0; i < ringParticleCount; i++) {
      const radius = 2.5 + Math.random() * 2;
      const angle = Math.random() * Math.PI * 2;
      const yOffset = (Math.random() - 0.5) * 0.6;

      ringPositions[i * 3] = Math.cos(angle) * radius;
      ringPositions[i * 3 + 1] = yOffset;
      ringPositions[i * 3 + 2] = Math.sin(angle) * radius;

      ringColors[i * 3] = 0.6 + Math.random() * 0.4;
      ringColors[i * 3 + 1] = 0.3 + Math.random() * 0.5;
      ringColors[i * 3 + 2] = 0.8 + Math.random() * 0.2;
    }

    ringGeometry.setAttribute('position', new THREE.BufferAttribute(ringPositions, 3));
    ringGeometry.setAttribute('color', new THREE.BufferAttribute(ringColors, 3));

    const ringMaterial = new THREE.PointsMaterial({
      size: 0.03,
      vertexColors: true,
      blending: THREE.AdditiveBlending,
      transparent: true,
      opacity: 0.7
    });

    const outerRing = new THREE.Points(ringGeometry, ringMaterial);
    scene.add(outerRing);

    // Gravitational lensing effect (warped space)
    const lensGeometry = new THREE.TorusGeometry(1.1, 0.05, 64, 200);
    const lensMaterial = new THREE.MeshStandardMaterial({
      color: 0x8844aa,
      emissive: 0x331166,
      emissiveIntensity: 0.8,
      transparent: true,
      opacity: 0.6,
      side: THREE.DoubleSide
    });
    const lensRing = new THREE.Mesh(lensGeometry, lensMaterial);
    lensRing.rotation.x = Math.PI / 2;
    scene.add(lensRing);

    // Second lens ring
    const lensGeometry2 = new THREE.TorusGeometry(1.3, 0.03, 64, 200);
    const lensMaterial2 = new THREE.MeshStandardMaterial({
      color: 0xff66aa,
      emissive: 0x441166,
      emissiveIntensity: 0.6,
      transparent: true,
      opacity: 0.5
    });
    const lensRing2 = new THREE.Mesh(lensGeometry2, lensMaterial2);
    lensRing2.rotation.x = Math.PI / 2 + 0.3;
    scene.add(lensRing2);

    // Particle system orbiting the black hole
    const orbitingParticles = [];
    const orbCount = 500;
    for (let i = 0; i < orbCount; i++) {
      const geometry = new THREE.SphereGeometry(0.02, 8, 8);
      const material = new THREE.MeshStandardMaterial({
        color: new THREE.Color().setHSL(0.6 + Math.random() * 0.3, 1, 0.5),
        emissive: 0x442266,
        emissiveIntensity: 0.5
      });
      const particle = new THREE.Mesh(geometry, material);
      particle.userData = {
        radius: 1.5 + Math.random() * 3,
        speed: 0.5 + Math.random() * 1.5,
        angle: Math.random() * Math.PI * 2,
        yOffset: (Math.random() - 0.5) * 0.8
      };
      scene.add(particle);
      orbitingParticles.push(particle);
    }

    // Relativistic jets (top and bottom)
    const jetParticleCount = 2000;
    const jetGeometry = new THREE.BufferGeometry();
    const jetPositions = new Float32Array(jetParticleCount * 3);
    const jetColors = new Float32Array(jetParticleCount * 3);

    for (let i = 0; i < jetParticleCount; i++) {
      const isTop = Math.random() > 0.5;
      const height = (Math.random() * 4 + 0.5) * (isTop ? 1 : -1);
      const radius = Math.random() * 0.8;
      const angle = Math.random() * Math.PI * 2;

      jetPositions[i * 3] = Math.cos(angle) * radius;
      jetPositions[i * 3 + 1] = height;
      jetPositions[i * 3 + 2] = Math.sin(angle) * radius;

      jetColors[i * 3] = 0.8 + Math.random() * 0.2;
      jetColors[i * 3 + 1] = 0.4 + Math.random() * 0.4;
      jetColors[i * 3 + 2] = 1.0;
    }

    jetGeometry.setAttribute('position', new THREE.BufferAttribute(jetPositions, 3));
    jetGeometry.setAttribute('color', new THREE.BufferAttribute(jetColors, 3));

    const jetMaterial = new THREE.PointsMaterial({
      size: 0.05,
      vertexColors: true,
      blending: THREE.AdditiveBlending
    });

    const jets = new THREE.Points(jetGeometry, jetMaterial);
    scene.add(jets);

    // Animation variables
    let time = 0;
    let starTwinkleTime = 0;

    // Animation loop
    const animate = () => {
      requestAnimationFrame(animate);

      time += 0.008;
      starTwinkleTime += 0.005;

      // Rotate accretion disk
      if (accretionDiskRef.current) {
        accretionDiskRef.current.rotation.y += 0.02;
        outerRing.rotation.y -= 0.01;
      }

      // Rotate lens rings
      lensRing.rotation.z += 0.01;
      lensRing.rotation.y += 0.005;
      lensRing2.rotation.z -= 0.008;
      lensRing2.rotation.x += 0.003;

      // Pulsating black hole center
      const pulse = 0.8 + Math.sin(time * 8) * 0.05;
      eventHorizon.scale.set(pulse, pulse, pulse);
      innerGlow.scale.set(1 + Math.sin(time * 6) * 0.03, 1 + Math.sin(time * 6) * 0.03, 1 + Math.sin(time * 6) * 0.03);

      // Update point light intensity
      pointLight.intensity = 0.8 + Math.sin(time * 4) * 0.3;

      // Update orbiting particles
      orbitingParticles.forEach(particle => {
        particle.userData.angle += 0.02 * particle.userData.speed;
        const x = Math.cos(particle.userData.angle) * particle.userData.radius;
        const z = Math.sin(particle.userData.angle) * particle.userData.radius;
        particle.position.set(x, particle.userData.yOffset, z);

        // Particle color animation
        const hue = (time + particle.userData.radius) % 1;
        particle.material.color.setHSL(hue, 1, 0.6);
      });

      // Rotate stars slowly
      stars.rotation.y += 0.0005;
      stars.rotation.x += 0.0003;
      stars2.rotation.y -= 0.0004;

      // Twinkling stars effect
      const twinkle = 0.5 + Math.sin(starTwinkleTime * 3) * 0.3;
      starMaterial.opacity = 0.6 + Math.sin(starTwinkleTime * 2) * 0.2;
      starMaterial2.opacity = 0.5 + Math.cos(starTwinkleTime * 2.5) * 0.2;

      // Rotate jets
      jets.rotation.y += 0.005;

      // Smooth camera movement when user is logged in
      if (user) {
        camera.position.x += (0 - camera.position.x) * 0.03;
        camera.position.y += (2 - camera.position.y) * 0.03;
      } else {
        camera.position.x += (Math.sin(time * 0.2) * 0.5 - camera.position.x) * 0.02;
        camera.position.y += (Math.cos(time * 0.3) * 0.3 - camera.position.y) * 0.02;
      }

      camera.lookAt(0, 0, 0);

      renderer.render(scene, camera);
    };

    animate();

    // Handle window resize
    const handleResize = () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    };

    window.addEventListener('resize', handleResize);

    // Cleanup
    return () => {
      window.removeEventListener('resize', handleResize);
      if (mountRef.current && renderer.domElement) {
        mountRef.current.removeChild(renderer.domElement);
      }
      renderer.dispose();
    };
  }, [user]);

  const handleLoginSuccess = (userData) => {
    console.log('Login successful:', userData);
    setUser(userData);
    setIsModalOpen(false);
  };

  const handleLogout = () => {
    localStorage.removeItem('user');
    localStorage.removeItem('isLoggedIn');
    setUser(null);
  };

  const openModal = () => {
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
  };

  if (isLoading) {
    return (
      <div style={{
        position: 'fixed',
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'center',
        alignItems: 'center',
        background: 'black',
        color: 'white',
        fontFamily: 'Arial, sans-serif',
        zIndex: 9999
      }}>
        <div style={{
          width: '60px',
          height: '60px',
          border: '4px solid rgba(255,255,255,0.3)',
          borderTopColor: 'white',
          borderRadius: '50%',
          animation: 'spin 1s linear infinite',
          marginBottom: '20px'
        }} />
        <style>{`
          @keyframes spin {
            to { transform: rotate(360deg); }
          }
        `}</style>
        <p>Loading Black Hole Experience...</p>
      </div>
    );
  }

  return (
    <div style={{ position: 'relative', minHeight: '100vh', overflow: 'hidden' }}>
      {/* Three.js Canvas Container */}
      <div ref={mountRef} style={{
        position: 'fixed',
        top: 0,
        left: 0,
        width: '100%',
        height: '100%',
        zIndex: 0
      }} />

      {/* Navigation Bar */}
      <nav style={{
        position: 'relative',
        zIndex: 100,
        background: 'rgba(0, 0, 0, 0.8)',
        backdropFilter: 'blur(10px)',
        borderBottom: '1px solid rgba(255,255,255,0.1)',
        padding: '1rem 2rem'
      }}>
        <div style={{
          maxWidth: '1400px',
          margin: '0 auto',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          flexWrap: 'wrap',
          gap: '1rem'
        }}>
          <div>
            <h1 style={{
              background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
              WebkitBackgroundClip: 'text',
              WebkitTextFillColor: 'transparent',
              backgroundClip: 'text',
              fontSize: '1.8rem',
              margin: 0
            }}>
              🕳️ Black Hole Dashboard
            </h1>
          </div>

          <div style={{
            display: 'flex',
            alignItems: 'center',
            gap: '2rem',
            flexWrap: 'wrap'
          }}>
            {user ? (
              <div style={{
                display: 'flex',
                alignItems: 'center',
                gap: '1rem',
                background: 'rgba(102, 126, 234, 0.2)',
                padding: '0.5rem 1rem',
                borderRadius: '50px'
              }}>
                <span style={{ color: 'white', fontWeight: '600' }}>
                  Welcome, {user.username}!
                </span>
                <button onClick={handleLogout} style={{
                  padding: '0.5rem 1.5rem',
                  background: 'linear-gradient(135deg, #e74c3c 0%, #c0392b 100%)',
                  color: 'white',
                  border: 'none',
                  borderRadius: '50px',
                  cursor: 'pointer',
                  fontWeight: '600',
                  transition: 'transform 0.3s ease'
                }}>
                  Logout
                </button>
              </div>
            ) : (
              <button onClick={openModal} style={{
                padding: '0.5rem 1.5rem',
                background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                color: 'white',
                border: 'none',
                borderRadius: '50px',
                cursor: 'pointer',
                fontWeight: '600',
                transition: 'transform 0.3s ease'
              }}>
                Login / Register
              </button>
            )}
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main style={{
        position: 'relative',
        zIndex: 10,
        maxWidth: '1400px',
        margin: '0 auto',
        padding: '2rem',
        minHeight: 'calc(100vh - 150px)'
      }}>
        {user ? (
          <div style={{
            animation: 'fadeInUp 0.6s ease-out'
          }}>
            <div style={{
              background: 'rgba(0, 0, 0, 0.7)',
              backdropFilter: 'blur(10px)',
              borderRadius: '20px',
              padding: '2rem',
              border: '1px solid rgba(255,255,255,0.1)'
            }}>
              <h2 style={{ color: 'white', marginBottom: '1rem', fontSize: '2rem' }}>
                Welcome to the Black Hole, {user.username}!
              </h2>
              <p style={{ color: '#aaa', marginBottom: '2rem', fontSize: '1.1rem' }}>
                You're now experiencing the gravitational pull of our interactive 3D black hole.
              </p>

              <div style={{
                background: 'rgba(0, 0, 0, 0.5)',
                padding: '1.5rem',
                borderRadius: '15px',
                borderLeft: '4px solid #667eea',
                marginBottom: '2rem'
              }}>
                <h3 style={{ color: 'white', marginBottom: '1rem' }}>Your Information:</h3>
                <p style={{ margin: '0.5rem 0', color: '#ccc' }}>
                  <strong>Username:</strong> {user.username}
                </p>
                {user.email && (
                  <p style={{ margin: '0.5rem 0', color: '#ccc' }}>
                    <strong>Email:</strong> {user.email}
                  </p>
                )}
                <p style={{ margin: '0.5rem 0', color: '#ccc' }}>
                  <strong>User ID:</strong> {user.id}
                </p>
              </div>

              <div style={{
                display: 'flex',
                gap: '1rem',
                flexWrap: 'wrap'
              }}>
                <button style={{
                  padding: '0.75rem 1.75rem',
                  background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                  color: 'white',
                  border: 'none',
                  borderRadius: '50px',
                  cursor: 'pointer',
                  fontWeight: '600'
                }}>
                  View Profile
                </button>
                <button style={{
                  padding: '0.75rem 1.75rem',
                  background: 'linear-gradient(135deg, #e74c3c 0%, #c0392b 100%)',
                  color: 'white',
                  border: 'none',
                  borderRadius: '50px',
                  cursor: 'pointer',
                  fontWeight: '600'
                }}>
                  Explore Space
                </button>
              </div>
            </div>
          </div>
        ) : (
          <div style={{ textAlign: 'center', padding: '3rem 0' }}>
            <div style={{
              background: 'rgba(0, 0, 0, 0.7)',
              backdropFilter: 'blur(10px)',
              borderRadius: '20px',
              padding: '3rem 4rem',
              display: 'inline-block',
              maxWidth: '80%',
              marginBottom: '4rem',
              border: '1px solid rgba(255,255,255,0.1)'
            }}>
              <h1 style={{
                fontSize: '3.5rem',
                background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                WebkitBackgroundClip: 'text',
                WebkitTextFillColor: 'transparent',
                backgroundClip: 'text',
                marginBottom: '1rem'
              }}>
                🕳️ BLACK HOLE
              </h1>
              <p style={{ fontSize: '1.3rem', color: '#ccc', marginBottom: '2rem' }}>
                Experience the gravitational pull of our interactive 3D black hole
              </p>
              <button onClick={openModal} style={{
                padding: '1rem 2.5rem',
                fontSize: '1.1rem',
                background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                color: 'white',
                border: 'none',
                borderRadius: '50px',
                cursor: 'pointer',
                fontWeight: '600',
                transition: 'transform 0.3s ease'
              }}>
                Enter the Event Horizon
              </button>
            </div>

            <div style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))',
              gap: '2rem',
              marginTop: '3rem'
            }}>
              {[
                { icon: '🌀', title: 'Gravitational Lensing', desc: 'Witness light bending around the event horizon' },
                { icon: '💫', title: 'Accretion Disk', desc: 'Spinning matter glowing at extreme temperatures' },
                { icon: '⚡', title: 'Relativistic Jets', desc: 'Powerful streams of plasma shooting outward' }
              ].map((feature, index) => (
                <div key={index} style={{
                  background: 'rgba(0, 0, 0, 0.7)',
                  backdropFilter: 'blur(10px)',
                  borderRadius: '20px',
                  padding: '2rem',
                  textAlign: 'center',
                  border: '1px solid rgba(255,255,255,0.1)',
                  transition: 'transform 0.3s ease'
                }}>
                  <div style={{ fontSize: '3.5rem', marginBottom: '1rem' }}>{feature.icon}</div>
                  <h3 style={{ color: 'white', marginBottom: '0.75rem' }}>{feature.title}</h3>
                  <p style={{ color: '#aaa' }}>{feature.desc}</p>
                </div>
              ))}
            </div>
          </div>
        )}
      </main>

      {/* Footer */}
      <footer style={{
        position: 'relative',
        zIndex: 10,
        background: 'rgba(0, 0, 0, 0.8)',
        backdropFilter: 'blur(10px)',
        color: 'white',
        borderTop: '1px solid rgba(255,255,255,0.1)',
        marginTop: 'auto'
      }}>
        <div style={{
          maxWidth: '1400px',
          margin: '0 auto',
          padding: '2rem',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          flexWrap: 'wrap',
          gap: '1rem'
        }}>
          <p style={{ color: '#aaa' }}>© 2026 Black Hole Experience. All rights reserved.</p>
          <div style={{ display: 'flex', gap: '2rem' }}>
            <a href="#" style={{ color: '#aaa', textDecoration: 'none' }}>Privacy</a>
            <a href="#" style={{ color: '#aaa', textDecoration: 'none' }}>Terms</a>
            <a href="#" style={{ color: '#aaa', textDecoration: 'none' }}>Help</a>
          </div>
        </div>
      </footer>

      {/* Login Modal */}
      <LoginModal
        isOpen={isModalOpen}
        onClose={closeModal}
        onLoginSuccess={handleLoginSuccess}
      />

      {/* Global Animations */}
      <style>{`
        @keyframes fadeInUp {
          from {
            opacity: 0;
            transform: translateY(30px);
          }
          to {
            opacity: 1;
            transform: translateY(0);
          }
        }

        @keyframes spin {
          to {
            transform: rotate(360deg);
          }
        }

        button:hover {
          transform: translateY(-2px) !important;
          box-shadow: 0 4px 20px rgba(102, 126, 234, 0.4) !important;
        }

        .feature-card:hover {
          transform: translateY(-10px) !important;
        }
      `}</style>
    </div>
  );
}

export default App;
